import {blockDay,currentDay,cycleLength,performanceLevel} from './study-method.js';
import {visibleSteps} from './study-state.js';
export const MAX_EXAM_QUESTIONS=80;
export function validateExamQuestions(ids){if(ids.length>MAX_EXAM_QUESTIONS)throw Error('Um simulado pode ter no máximo 80 questões.');return ids;}
const sum=(rows,key)=>rows.reduce((n,r)=>n+Number(r[key]||0),0);
export function topicStats(data,uid){const groups=new Map();for(const l of data.study_logs.filter(l=>l.student_id===uid)){const key=l.topic_key||l.subject+'|'+l.topic;const g=groups.get(key)||{key,subject:l.subject,topic:l.topic,total:0,correct:0,logs:[]};g.total+=Number(l.total||0);g.correct+=Number(l.correct||0);g.logs.push(l);groups.set(key,g);}return [...groups.values()].map(g=>({...g,...performanceLevel(g.total,g.correct)}));}
export function studentSummary(data,p,today=new Date().toISOString().slice(0,10)){
 const logs=data.study_logs.filter(l=>l.student_id===p.id),sessions=(data.study_sessions||[]).filter(s=>s.student_id===p.id),cycles=data.cycles.filter(c=>c.student_id===p.id&&c.status==='Publicado').sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||'')),cycle=cycles[0],day=cycle?currentDay(cycle,data.progress):0;
 const tasks=cycle?cycle.blocks.flatMap(b=>visibleSteps(cycle,b,data).map(step=>({day:blockDay(b,cycle),done:!!data.method_studies.find(s=>s.cycle_id===cycle.id&&s.block_id===b.id)?.flags?.[step.id]}))):[],done=tasks.filter(t=>t.done).length,weekStart=Math.floor(Math.max(0,day-1)/7)*7+1,week=tasks.filter(t=>t.day>=weekStart&&t.day<weekStart+7),reviews=data.method_reviews.filter(r=>r.student_id===p.id&&r.cycle_id===cycle?.id&&r.status==='pending'),due=reviews.filter(r=>r.due_day<=day),overdue=due.filter(r=>r.due_day<day);
 const from=n=>new Date(Date.parse(today+'T00:00:00Z')-n*86400000).toISOString().slice(0,10),recent=logs.filter(l=>l.date>=from(6)&&l.date<=today),previous=logs.filter(l=>l.date>=from(13)&&l.date<from(6)),recentTotal=sum(recent,'total'),previousTotal=sum(previous,'total'),trend=recentTotal&&previousTotal?sum(recent,'correct')/recentTotal*100-sum(previous,'correct')/previousTotal*100:null;
 const last=[...logs.filter(l=>l.total>0||l.minutes>0).map(l=>l.date),...sessions.filter(s=>s.focused_seconds>0).map(s=>(s.heartbeat_at||s.ended_at||s.started_at||s.created_at||'').slice(0,10)),...data.method_studies.filter(s=>s.student_id===p.id&&s.studied_at).map(s=>s.studied_at.slice(0,10))].filter(Boolean).sort().at(-1)||null;
 return {cycle,day,length:cycle?cycleLength(cycle):0,done,pending:tasks.length-done,rate:tasks.length?done/tasks.length*100:0,weekRate:week.length?week.filter(t=>t.done).length/week.length*100:null,total:sum(logs,'total'),correct:sum(logs,'correct'),seconds:sum(sessions,'focused_seconds'),recentSeconds:sum(sessions.filter(s=>(s.started_at||s.created_at||'').slice(0,10)>=from(6)),'focused_seconds'),recentTotal,recentCorrect:sum(recent,'correct'),trend,last,due:due.length,overdue:overdue.length,pendingReviews:reviews.length,weak:topicStats(data,p.id).filter(t=>t.total&&t.correct/t.total<.6).sort((a,b)=>a.correct/a.total-b.correct/b.total),level:performanceLevel(sum(logs,'total'),sum(logs,'correct'))};
}
export function studyHistory(data,uid,key){const groups=new Map();const add=(date,subject,topic,topicKey)=>{const id=[date,topicKey||subject+'|'+topic].join('|');if(!groups.has(id))groups.set(id,{date,subject,topic,key:topicKey,total:0,correct:0,seconds:0,manualMinutes:0,notes:[],review:false});return groups.get(id);};
 for(const l of data.study_logs.filter(l=>l.student_id===uid&&(!key||l.topic_key===key))){const g=add(l.date,l.subject,l.topic,l.topic_key);g.total+=Number(l.total||0);g.correct+=Number(l.correct||0);if(l.origin!=='timer'&&!l.session_id&&!l.study_session_id)g.manualMinutes+=Number(l.minutes||0);if(l.notes)g.notes.push(l.notes);if(l.method_review_id)g.review=true;}
 for(const s of (data.study_sessions||[]).filter(s=>s.student_id===uid&&s.focused_seconds>0&&(!key||s.topic_key===key))){const date=data.study_logs.find(l=>l.session_id===s.id)?.date||new Date(s.started_at||s.created_at).toLocaleDateString('en-CA',{timeZone:'America/Bahia'}),g=add(date,s.subject,s.topic,s.topic_key);g.seconds+=Number(s.focused_seconds);}
 return [...groups.values()].sort((a,b)=>b.date.localeCompare(a.date));
}
